SELECT DISTINCT OH.ORDER_ID, OH.PRIORITY, OH.ORDER_DATE FROM ORDER_HEADER OH INNER JOIN ORDER_IDENTIFICATION SHOPIFY_OID ON OH.ORDER_ID = SHOPIFY_OID.ORDER_ID AND (((SHOPIFY_OID.FROM_DATE  IS NULL OR SHOPIFY_OID.FROM_DATE <= '2026-09-11 15:10:25.442000') AND (SHOPIFY_OID.THRU_DATE  IS NULL OR SHOPIFY_OID.THRU_DATE > '2026-09-11 15:10:25.442000')) AND SHOPIFY_OID.ORDER_IDENTIFICATION_TYPE_ID = 'SHOPIFY_ORD_ID') LEFT OUTER JOIN ORDER_IDENTIFICATION OID ON OH.ORDER_ID = OID.ORDER_ID AND (((OID.FROM_DATE  IS NULL OR OID.FROM_DATE <= '2026-09-11 15:10:25.442000') AND (OID.THRU_DATE  IS NULL OR OID.THRU_DATE > '2026-09-11 15:10:25.442000')) AND OID.ORDER_IDENTIFICATION_TYPE_ID = 'NETSUITE_ORDER_ID') LEFT OUTER JOIN (SELECT UOI.ORDER_ID AS ORDER_ID FROM ORDER_ITEM UOI LEFT OUTER JOIN GOOD_IDENTIFICATION UGID ON UOI.PRODUCT_ID = UGID.PRODUCT_ID AND (((UGID.FROM_DATE  IS NULL OR UGID.FROM_DATE <= '2026-09-11 15:10:25.442000') AND (UGID.THRU_DATE  IS NULL OR UGID.THRU_DATE > '2026-09-11 15:10:25.442000')) AND UGID.GOOD_IDENTIFICATION_TYPE_ID = 'NETSUITE_PRODUCT_ID') WHERE UGID.ID_VALUE IS NULL) UNMAP ON OH.ORDER_ID = UNMAP.ORDER_ID LEFT OUTER JOIN (SELECT XOPP.ORDER_ID AS ORDER_ID FROM ORDER_PAYMENT_PREFERENCE XOPP LEFT OUTER JOIN INVOICE XCRI ON XOPP.CUSTOMER_RETURN_INVOICE_ID = XCRI.INVOICE_ID WHERE (XOPP.PAYMENT_METHOD_TYPE_ID = 'EXCHANGE_CREDIT' AND XOPP.STATUS_ID IN ('PAYMENT_AUTHORIZED', 'PAYMENT_SETTLED') AND XCRI.EXTERNAL_ID IS NULL)) XCM ON OH.ORDER_ID = XCM.ORDER_ID LEFT OUTER JOIN (SELECT POH.ORDER_ID AS ORDER_ID FROM ORDER_HEADER POH) PAID ON OH.ORDER_ID = PAID.ORDER_ID LEFT OUTER JOIN ORDER_ITEM_SHIP_GROUP SG ON OH.ORDER_ID = SG.ORDER_ID LEFT OUTER JOIN FACILITY_GROUP_MEMBER FGM ON SG.FACILITY_ID = FGM.FACILITY_ID AND ((FGM.FROM_DATE  IS NULL OR FGM.FROM_DATE <= '2026-09-11 15:10:25.442000') AND (FGM.THRU_DATE  IS NULL OR FGM.THRU_DATE > '2026-09-11 15:10:25.442000')) WHERE (OH.PRODUCT_STORE_ID = 'STORE' AND FGM.FACILITY_GROUP_ID = 'NETSUITE_FULFILLMENT' AND OH.ORDER_DATE > '2026-01-01T00:00:00' AND OH.ORDER_TYPE_ID = 'SALES_ORDER' AND SHOPIFY_OID.ID_VALUE IS NOT NULL AND OID.ORDER_ID IS NULL AND UNMAP.ORDER_ID IS NULL AND XCM.ORDER_ID IS NULL AND (PAID.ORDER_ID IS NOT NULL OR OH.GRAND_TOTAL = 0)) ORDER BY OH.PRIORITY ASC, OH.ORDER_DATE ASC, OH.ORDER_ID ASC LIMIT 500 OFFSET 0
